-- 制造执行（MES）演示数据：PostgreSQL
-- 在 Flyway 已迁移完成的 tuoyu-mes 库上执行，只写默认租户（tenant_id = 'default'），不改动 tuoyu-cloud 库。
-- 用户相关的字段（创建者、作业人、处理人、班组成员等）都是超级管理员 admin（用户 1761100000000000001，部门 1761000000000000103）。
-- 主键都在演示号段 1769000000000000000 ~ 1769000000009999999 内，每张表一段（见下表）。
-- 脚本开头先删除上次写入的演示数据，以及在演示工单、设备、计划上产生的业务数据，所以可以重复执行。
-- 时间都相对执行时刻：过去的业务时间写成“今天减若干天的某个钟点”或“当前时间减若干分钟”，计划日期可以是将来。
-- 编码规则与流水号不写入；单据编号是固定的演示编号（DEMO-WO-0001 等）。
--
-- 号段（主键范围）：
--   mes_factory                  factory_id         1769000000000100000 ~ 1769000000000199999
--   mes_workshop                 workshop_id        1769000000000200000 ~ 1769000000000299999
--   mes_line                     line_id            1769000000000300000 ~ 1769000000000399999
--   mes_station                  station_id         1769000000000400000 ~ 1769000000000499999
--   mes_team                     team_id            1769000000000500000 ~ 1769000000000599999
--   mes_team_member              member_id          1769000000000600000 ~ 1769000000000699999
--   mes_material                 material_id        1769000000000700000 ~ 1769000000000799999
--   mes_bom                      bom_id             1769000000000800000 ~ 1769000000000899999
--   mes_bom_item                 item_id            1769000000000900000 ~ 1769000000000999999
--   mes_route                    route_id           1769000000001000000 ~ 1769000000001099999
--   mes_route_operation          operation_id       1769000000001100000 ~ 1769000000001199999
--   mes_device                   device_id          1769000000001200000 ~ 1769000000001299999
--   mes_warehouse                warehouse_id       1769000000001300000 ~ 1769000000001399999
--   mes_location                 location_id        1769000000001400000 ~ 1769000000001499999
--   mes_downtime_reason          reason_id          1769000000001500000 ~ 1769000000001599999
--   mes_inspection_scheme        scheme_id          1769000000001600000 ~ 1769000000001699999
--   mes_andon_rule               andon_rule_id      1769000000001700000 ~ 1769000000001799999
--   mes_label_template           label_template_id  1769000000001800000 ~ 1769000000001899999
--   mes_check_item               check_item_id      1769000000001900000 ~ 1769000000001999999
--   mes_maintenance_plan         plan_id            1769000000002000000 ~ 1769000000002099999
--   mes_oee_config               config_id          1769000000002100000 ~ 1769000000002199999
--   mes_workorder                workorder_id       1769000000002200000 ~ 1769000000002299999
--   mes_operation_task           task_id            1769000000002300000 ~ 1769000000002399999
--   mes_production_report        report_id          1769000000002400000 ~ 1769000000002499999
--   mes_inspection               inspection_id      1769000000002500000 ~ 1769000000002599999
--   mes_defect_record            defect_id          1769000000002600000 ~ 1769000000002699999
--   mes_material_request         request_id         1769000000002700000 ~ 1769000000002799999
--   mes_material_request_item    item_id            1769000000002800000 ~ 1769000000002899999
--   mes_stock_in                 stock_in_id        1769000000002900000 ~ 1769000000002999999
--   mes_sn                       sn_id              1769000000003000000 ~ 1769000000003099999
--   mes_andon_event              event_id           1769000000003100000 ~ 1769000000003199999
--   mes_check_record             check_record_id    1769000000003200000 ~ 1769000000003299999
--   mes_check_record_detail      detail_id          1769000000003300000 ~ 1769000000003399999
--   mes_maintenance_order        order_id           1769000000003400000 ~ 1769000000003499999
--   mes_status_log               log_id             1769000000003500000 ~ 1769000000003599999

set client_encoding = 'UTF8';

begin;

-- ----------------------------
-- 清除：先子表后主表
-- ----------------------------
delete from mes_status_log where log_id between 1769000000003500000 and 1769000000003599999 or biz_id between 1769000000000000000 and 1769000000009999999;
delete from mes_maintenance_order where order_id between 1769000000003400000 and 1769000000003499999 or plan_id between 1769000000002000000 and 1769000000002099999;
delete from mes_check_record_detail where detail_id between 1769000000003300000 and 1769000000003399999 or check_record_id in (select check_record_id from mes_check_record where check_record_id between 1769000000003200000 and 1769000000003299999 or device_id between 1769000000001200000 and 1769000000001299999);
delete from mes_check_record where check_record_id between 1769000000003200000 and 1769000000003299999 or device_id between 1769000000001200000 and 1769000000001299999;
delete from mes_andon_event where event_id between 1769000000003100000 and 1769000000003199999;
delete from mes_sn where sn_id between 1769000000003000000 and 1769000000003099999 or workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_stock_in where stock_in_id between 1769000000002900000 and 1769000000002999999 or workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_material_request_item where item_id between 1769000000002800000 and 1769000000002899999 or request_id in (select request_id from mes_material_request where request_id between 1769000000002700000 and 1769000000002799999 or workorder_id between 1769000000002200000 and 1769000000002299999);
delete from mes_material_request where request_id between 1769000000002700000 and 1769000000002799999 or workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_defect_record where defect_id between 1769000000002600000 and 1769000000002699999 or workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_inspection where inspection_id between 1769000000002500000 and 1769000000002599999 or workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_production_report where report_id between 1769000000002400000 and 1769000000002499999 or workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_operation_task where task_id between 1769000000002300000 and 1769000000002399999 or workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_workorder where workorder_id between 1769000000002200000 and 1769000000002299999;
delete from mes_oee_config where config_id between 1769000000002100000 and 1769000000002199999 or target_id between 1769000000000300000 and 1769000000000399999 or target_id between 1769000000001200000 and 1769000000001299999;
delete from mes_maintenance_plan where plan_id between 1769000000002000000 and 1769000000002099999;
delete from mes_check_item where check_item_id between 1769000000001900000 and 1769000000001999999 or device_id between 1769000000001200000 and 1769000000001299999;
delete from mes_label_template where label_template_id between 1769000000001800000 and 1769000000001899999;
delete from mes_andon_rule where andon_rule_id between 1769000000001700000 and 1769000000001799999;
delete from mes_inspection_scheme where scheme_id between 1769000000001600000 and 1769000000001699999;
delete from mes_downtime_reason where reason_id between 1769000000001500000 and 1769000000001599999;
delete from mes_location where location_id between 1769000000001400000 and 1769000000001499999 or warehouse_id between 1769000000001300000 and 1769000000001399999;
delete from mes_warehouse where warehouse_id between 1769000000001300000 and 1769000000001399999;
delete from mes_device where device_id between 1769000000001200000 and 1769000000001299999;
delete from mes_route_operation where operation_id between 1769000000001100000 and 1769000000001199999 or route_id between 1769000000001000000 and 1769000000001099999;
delete from mes_route where route_id between 1769000000001000000 and 1769000000001099999;
delete from mes_bom_item where item_id between 1769000000000900000 and 1769000000000999999 or bom_id between 1769000000000800000 and 1769000000000899999;
delete from mes_bom where bom_id between 1769000000000800000 and 1769000000000899999;
delete from mes_material where material_id between 1769000000000700000 and 1769000000000799999;
delete from mes_team_member where member_id between 1769000000000600000 and 1769000000000699999 or team_id between 1769000000000500000 and 1769000000000599999;
delete from mes_team where team_id between 1769000000000500000 and 1769000000000599999;
delete from mes_station where station_id between 1769000000000400000 and 1769000000000499999;
delete from mes_line where line_id between 1769000000000300000 and 1769000000000399999;
delete from mes_workshop where workshop_id between 1769000000000200000 and 1769000000000299999;
delete from mes_factory where factory_id between 1769000000000100000 and 1769000000000199999;

