-- 安灯升级规则（2 行）
-- 已有相同“异常类型 + 紧急程度”组合的规则时跳过（规则按组合唯一）
select 1769000000001700001, '紧急事件 15 分钟响应', null, 'urgent', 15, 120, 'critical', '1761100000000000001', '0', '演示数据：紧急事件超时升为停线', 'default', 1761000000000000103, 1761100000000000001, current_date - 40 + time '09:00', 1761100000000000001, current_date - 40 + time '09:00', '0' where not exists (select 1 from mes_andon_rule where tenant_id = 'default' and del_flag = '0' and event_type is null and event_level = 'urgent');
select 1769000000001700002, '其他事件 30 分钟响应', null, null, 30, 480, 'urgent', '1761100000000000001', '0', '演示数据：适用于没有更具体规则的事件', 'default', 1761000000000000103, 1761100000000000001, current_date - 40 + time '09:00', 1761100000000000001, current_date - 40 + time '09:00', '0' where not exists (select 1 from mes_andon_rule where tenant_id = 'default' and del_flag = '0' and event_type is null and event_level is null);

-- 标签模板（2 行）
