select 1769000000001800002, '演示批次标签', 'batch', 80, 50, 1, 0, 'code128', 'batchCode,workorderCode,materialCode,materialName,quantity,productionDate', case when exists (select 1 from mes_label_template where tenant_id = 'default' and del_flag = '0' and target_type = 'batch' and default_flag = '1') then '0' else '1' end, '0', '演示数据', 'default', 1761000000000000103, 1761100000000000001, current_date - 40 + time '09:00', 1761100000000000001, current_date - 40 + time '09:00', '0';

